-- 2218 🏋️ Exercises from the book "diego-simeone-defending-tactics-tactical-analysis-and-sessions-from-atl-tico-mad" into the exercise catalog (mig 2191).
-- Every practice the book sets out, in OUR OWN WORDS, with app page numbers
-- (the diagram is the book page).  Written by scripts/exercises/sync.py load.
-- Re-runnable: clears this book's exercises first.
BEGIN;
DELETE FROM exercises WHERE book_id = (SELECT id FROM coaching_books WHERE slug = 'diego-simeone-defending-tactics-tactical-analysis-and-sessions-from-atl-tico-mad');
INSERT INTO exercises (title, category_id, opposition, moment, source_id, book_id, page_from, page_to, source_ref, coach,
  objective, setup, procedure, rules, progressions, coaching_points, players_text, min_players, max_players,
  area_text, area_length_m, area_width_m, duration_min, has_goals, has_keepers, directional, age_text, sort_order)
SELECT v.t, c.id, v.opp, v.m, b.source_id, b.id, v.pf::int, v.pt::int, v.ref, v.coach, v.obj, v.setup, v.proc, v.rules, v.prog, v.cp,
  v.players, v.mn::int, v.mx::int, v.area, v.len::real, v.wid::real, v.dur::real, v.goals::boolean, v.gk::boolean, v.dir::boolean, v.age, v.so
FROM (VALUES
  ('Front two keep balance, deny between lines', 'defending', 'overload', 'out_of_possession', 24, 24, 'Tactical Situation 1 practice: Forwards Retain Balance and Deny Space Between the Lines in a 4v5 (+GK) Functional Practice', 'Simeone (Atletico Madrid)', 'Two forwards and two central midfielders stop through passes and switches when the opponent builds up from the back.', 'Main area in the opposition half with a large goal and GK; 2 red forwards and 2 red central mids face 2 white centre backs and 2 white central mids on cones, plus a white No.10 waiting in a yellow target zone behind the reds.', 'GK plays out to a centre back; whites try to get the ball to No.10 directly or through their midfielders. The red forwards shift together (one presses, the other drops diagonally), keep the gap to their midfielders small and watch the weak-side centre back; on a turnover the reds counter at the big goal.', 'Reds must finish the counter attack within 8 seconds.', NULL, 'Angles and body shape that cut off through passes; deny space between the lines; counter straight at goal once the ball is won.', '4v5 (+GK)', 10, 10, NULL, NULL, NULL, NULL, true, true, true, NULL, 10),
  ('Deep forward covers when partner is high', 'defending', 'overload', 'out_of_possession', 35, 36, 'Tactical Situation 2 practice: Defensive Reactions when the Positioning of 1 Forward is Incorrect in a Zonal Practice', 'Simeone (Atletico Madrid)', 'Stop a through pass or switch of play until the advanced forward has had time to drop back into a sound defensive position.', 'Four marked zones in the opposition half with a large goal and GK in the box; white centre backs 4 and 5, white central mids 6 and 8, and white No.10 in a yellow target zone; 4 reds (forwards 7 and 9, central mids 14 and 8) start on cones, with forward 7 starting too high.', 'GK passes to a white centre back, who tries to find No.10 directly or via a midfielder. The deeper red forward (9) stays tight to his midfielders to block the inside pass instead of pressing; once 7 has recovered, 9 presses the ball and the reds close all passing lanes to win it, then counter at the big goal.', 'Counter attack must end in a shot within 8 seconds.', 'Two phases shown: 1) defensive reactions and movements, 2) win the ball and counter. Book notes it can be set up against a 4-3-3.', 'Angles and body shape to block through passes; stop the switch with well-timed pressing; quick direct counter once the ball is won.', '4v5 (+GK)', 10, 10, NULL, NULL, NULL, NULL, true, true, true, NULL, 20),
  ('Counter-ready front two vs two centre backs', 'defending', 'overload', 'out_of_possession', 43, 44, 'Tactical Situation 3 practice: Positioning of the Forwards to Prepare for Counter Attacks in a 4v5 (+GK) Functional Practice', 'Simeone (Atletico Madrid)', 'Block through passes and switches while one forward stays high between the centre backs ready for a counter.', 'Main area in the opposition half with a large goal and GK; red forwards 18 and 7 plus red central mids 14 and 8 against white centre backs 4 and 5 and white central mids 6 and 8, with a white No.10 in a yellow target zone; all start on cones.', 'GK plays out and whites try to reach No.10. After a switch between the centre backs the reds take counter-minded positions: the deeper forward (7) stays near his midfielders to block passing options while the advanced forward (18) sits between the centre backs. When the reds win it they release 18 quickly and attack the big goal.', 'Counter attack must finish within 8 seconds.', 'Two phases: 1) defensive reactions and movements against 2 centre backs, 2) win the ball and counter. Can be adapted to play against a 4-3-3.', 'Angles and body shape to block through passes; deny space between the lines; counter fast by finding the advanced forward.', '4v5 (+GK)', 10, 10, NULL, NULL, NULL, NULL, true, true, true, NULL, 30),
  ('Compact midfield four blocks through passes', 'defending', 'overload', 'out_of_possession', 51, 52, 'Tactical Situation 4 practice: Compact Midfield Line Blocking Through Passes in a Functional Game', 'Simeone (Atletico Madrid)', 'A midfield line of four shifts with the ball, keeps a safety distance from the ball carrier and closes the lanes for through passes.', 'Main area just outside a penalty box with two mini goals on the edge of the box; 4 red midfielders face a white back four (2 centre backs, 2 full backs); two white forwards (9 and 10) wait in a yellow end zone behind the reds.', 'Scenario A: the white defenders pass among themselves from set positions and look for a through pass to a forward in the yellow zone, while the red midfielders slide across, stay compact and block the lanes. Scenario B: the white defenders may now dribble forward or drop off, so the reds must step back or up to keep their safety distance and form a pressing triangle. Reds who win the ball counter quickly at either mini goal.', 'Counter attack must score in either mini goal within a set time.', 'Scenario B lets the white defenders carry the ball forward or back, changing the distance the midfield line must hold.', 'Keep a safety distance at all times; angles and body shape to block through passes; quick counter once the ball is won.', '4v4 plus 2 target forwards (4v6)', 10, 10, NULL, NULL, NULL, NULL, true, false, true, NULL, 40),
  ('Two centre backs defend long balls to lone striker', 'defending', 'opposed', 'out_of_possession', 67, 68, 'Tactical Situation 5 Practice 1', 'Simeone (Atletico Madrid)', 'Two centre backs read medium and long passes aimed at a single forward and either step in front to clear or cover the space behind.', 'Marked zone in front of the penalty area with a GK in a full goal; 2 red centre backs in the zone with 1 white forward; 4 white players (2 full backs, 2 central mids) spread along the halfway line.', 'The deep whites move the ball between set positions, then one plays a long pass to the forward''s feet or into the space behind. The strong-side centre back anticipates and gets ahead of the forward to clear wide-area passes, while the partner covers balls played over the top; if the forward receives facing goal he shoots, if back to goal he is pressed so he must play back.', NULL, 'Scenario A: pass to feet, centre back steps in front to clear. Scenario B: pass over the first centre back''s head, partner covers and clears.', 'Both centre backs shift together with the ball; strong-side CB defends with anticipation and gets in front; weak-side CB covers passes over his partner and tracks the forward tightly.', '5v2+GK', 8, 8, NULL, NULL, NULL, NULL, true, true, true, NULL, 50),
  ('Two centre backs versus two strikers long balls', 'defending', 'opposed', 'out_of_possession', 69, 70, 'Tactical Situation 5 Practice 2', 'Simeone (Atletico Madrid)', 'Centre backs defend long passes against two forwards (4-4-2), staying goal-side, stopping the turn and covering each other.', 'Same as the previous practice (zone in front of the box, GK in goal, 4 deep whites on the halfway line) but now 2 white forwards in the zone against the 2 red centre backs.', 'Deep whites circulate then play long to either forward. The strong-side centre back no longer tries to get in front; he stays goal-side, prevents the turn inside, forces the forward wide and tries to provoke a poor first touch, while the weak-side centre back drops back and across to cover and still watch his own forward.', 'Passes must land in the marked zone or the penalty area.', 'Scenario A: pass from a central area. Scenario B: pass from a wide area, where the strong-side CB may step in front only if he has time. Variation: aim passes at the weak-side forward to test the other centre back.', 'Shift with the ball; strong-side CB goal-side of his forward; weak-side CB both supports his partner and controls his own man.', '6v2+GK', 9, 9, NULL, NULL, NULL, NULL, true, true, true, NULL, 60),
  ('Centre backs defend striker plus number 10', 'defending', 'opposed', 'out_of_possession', 71, 72, 'Tactical Situation 5 Practice 3', 'Simeone (Atletico Madrid)', 'Centre backs read where the opposing No.10 is (deep or advanced) and adjust between double-marking the striker and marking one man each (4-2-3-1).', 'Same zone, GK and 4 deep whites; 1 white forward in the zone and 1 white No.10 who starts either outside (deep) or inside (advanced) the marked area, against 2 red centre backs.', 'Long passes go to the forward or No.10. With the No.10 deep, both centre backs focus on the striker and step in front to clear when they can; with the No.10 advanced, one centre back goes goal-side of the striker, stops the turn and forces him wide while the other controls the No.10 and covers.', 'Passes must land in the marked zone or the penalty area.', 'Scenario A: No.10 deep. Scenario B: No.10 advanced inside the zone. Variation: pass to the weak-side attacker.', 'Shift collectively with the ball; read the No.10''s position and react to the specific situation.', '6v2+GK', 9, 9, NULL, NULL, NULL, NULL, true, true, true, NULL, 70),
  ('Wide full backs contest wingers vs 4-3-3', 'defending', 'opposed', 'out_of_possession', 78, 79, 'Tactical Situation 6 Practice 1', 'Simeone (Atletico Madrid)', 'Full backs hold wide positions and shift across so they can intercept passes to the opposing wingers or close them down quickly.', 'Central white zone in front of the box holding a white forward and 4 red defenders; two wide yellow zones each holding a white winger; 4 deep whites on the halfway line; GK in a full goal.', 'Deep whites move the ball and the back four shift with it, centre backs on the forward and full backs close to the wingers. A deep white then plays to a winger; the near full back tries to intercept or else limits his time and space in the yellow zone. The winger tries to beat his man 1v1 and cross for the forward to finish.', NULL, 'Scenario A: pass to the winger from a central player. Scenario B: long switch of play to the far winger, weak-side full back readjusts after the switch. Variation: deep players sometimes feed the striker to test the centre backs.', 'Full backs stay wide and close to their winger; whole line shifts with the ball; aggressive intercepts where possible.', '7v4+GK', 12, 12, NULL, NULL, NULL, NULL, true, true, true, NULL, 80),
  ('Full backs contest wingers vs 4-4-2 and 4-2-3-1', 'defending', 'opposed', 'out_of_possession', 80, 81, 'Tactical Situation 6 Practice 2', 'Simeone (Atletico Madrid)', 'Full backs take more balanced positions against a two-striker or No.10 shape and still restrict or intercept passes to wingers.', 'Same as the previous practice but with an extra white attacker (second forward or a No.10) so the back four face 4-4-2 or 4-2-3-1 shapes.', 'Deep whites circulate and switch play to a winger in a yellow zone. Against 4-4-2 the full back sits narrower and focuses on denying time and space once the winger receives; against 4-2-3-1 the full backs read the No.10: if he is deep they stay wide and get in front to clear, if he is advanced they tuck in near the centre backs. Wingers play 1v1 and cross for a finish.', NULL, 'Scenario A: vs 4-4-2, restrict the winger after a switch. Scenario B: vs 4-2-3-1, intercept the long pass to the winger when the No.10 is deep.', 'Shift according to the ball; focus on controlling the direct opponent.', '8v4+GK', 13, 13, NULL, NULL, NULL, NULL, true, true, true, NULL, 90),
  ('Centre backs close gaps to full backs', 'defending', 'opposed', 'out_of_possession', 93, 94, 'Session (Tactical Situation 7): Practice 1', 'Simeone (Atletico Madrid)', 'Centre backs shift horizontally to close the gaps between themselves and the full backs when attacking midfielders run into them.', 'White zone in front of a yellow zone at the edge of the box; 2 red centre backs and a white forward in the yellow zone, 2 white attacking midfielders in the white zone, 3 deep whites on the halfway line, mannequins on each side as the full backs, GK in a full goal.', 'Deep whites pass between set positions while the attacking midfielders run into the gaps beside the centre backs to get a pass in behind and shoot. The centre back on that side shifts across, controls the runner and clears long or ground passes played into the gap.', 'Passes must go into the yellow zone or penalty area; only one attacking midfielder may run forward at a time.', 'Scenario A: pass into the gap on the weak side. Scenario B: ground pass into the gap on the strong side. Variation: play vs 4-2-3-1 with a single No.10 making the runs.', 'Shift with the ball; open body shape to see the space and the midfielders.', '6v2+GK', 9, 9, NULL, NULL, NULL, NULL, true, true, true, NULL, 100),
  ('Full backs close gaps to centre backs', 'defending', 'opposed', 'out_of_possession', 95, 96, 'Session (Tactical Situation 7): Practice 2', 'Simeone (Atletico Madrid)', 'Full backs read the play and shift inside to close the gap to the centre backs against runs from attacking midfielders.', 'Two yellow wide zones replace the central one; red full backs in them with a white winger outside each, mannequins as the centre backs, 2 white attacking midfielders in the white zone, 3 deep whites, GK in goal.', 'Deep whites circulate; when an attacking midfielder runs into the white zone towards the gap, the near full back shifts inside to control him and cut out the pass, clearing long or ground balls played into the gap.', 'Passes must go into the yellow zones or penalty area; only one attacking midfielder may run at a time.', 'Scenario A: gap on the weak side. Scenario B: gap on the strong side. Variation: vs 4-2-3-1 with only a No.10 running.', 'Shift with the ball; full backs, especially on the strong side, keep an open body shape to watch space and midfielders.', '7v2+GK', 10, 10, NULL, NULL, NULL, NULL, true, true, true, NULL, 110),
  ('Back four controls gaps between defenders', 'defending', 'opposed', 'out_of_possession', 97, 97, 'Session (Tactical Situation 7): Practice 3', 'Simeone (Atletico Madrid)', 'The full back four reads runs into the gaps between centre backs and full backs and shifts and communicates to close them.', 'Full-width yellow zone at the edge of the box holding 4 red defenders, a white forward and white wingers on each side; 2 white attacking midfielders in the white zone ahead; 3 deep whites; GK in goal.', 'Deep whites move the ball and can also feed the wingers; both attacking midfielders may make forward runs into the gaps. The whites try to score while the back four uses open body shape and horizontal shifting to defend every situation.', NULL, 'Variation: vs 4-2-3-1 with only a No.10 making runs into the gaps.', 'Shift with the ball; open body shape and a wide view; clear constant communication between the defenders.', '8v4+GK', 13, 13, NULL, NULL, NULL, NULL, true, true, true, NULL, 120),
  ('Front block blocks through passes 6v6', 'defending', 'opposed', 'out_of_possession', 114, 114, 'Session for Tactical Situation 8: Practice 1', 'Simeone (Atletico Madrid)', 'Front block of 2 forwards and 4 midfielders shifts as a compact unit to keep passing lanes into the central forward zone closed.', 'Half pitch plus a yellow zone in front of the halfway line. 4 white defenders with 2 white forwards inside the yellow zone; 6 reds (2 forwards, 4 midfielders) between them; white GK in the big goal.', 'White defenders move the ball between set positions looking for a through pass to a forward in the yellow zone. Reds slide with the ball, keep a safety distance and stay tight together to cut out the through pass. On winning it the reds counter at the big goal.', 'Reds must score past the GK within 8-10 seconds of winning the ball.', NULL, 'Shift with the ball; keep horizontal spacing in the midfield line; keep vertical spacing between forward and midfield lines.', '6v6+GK', 13, 13, 'Half pitch with central yellow zone', NULL, NULL, NULL, true, true, true, NULL, 130),
  ('Front block blocks through passes 6v8', 'defending', 'overload', 'out_of_possession', 115, 116, 'Session for Tactical Situation 8: Practice 2', 'Simeone (Atletico Madrid)', 'Front block keeps lanes narrow and the space between lines small against added link midfielders, and reacts when a centre back carries the ball forward.', 'As practice 1 but whites add 2 central midfielders between the lines (4 defenders, 2 CMs, 2 forwards in the yellow zone) against 6 reds; white GK in the big goal.', 'Scenario A: whites use the 2 midfielders as links to reach the forwards; reds shift together, narrow the lanes and stop the midfielders turning. Scenario B: the coach lets a white centre back dribble forward unpressed; red midfielders drop off to a safe distance, get compact and still block the through pass. Reds counter after a win.', 'Reds score past the GK within 8-10 seconds of winning the ball.', 'Scenario A narrow lanes and limit space between lines; Scenario B centre back dribbles through the pressure.', 'Shift with the ball; read the situation; keep horizontal and vertical distances.', '6v8+GK', 15, 15, 'Half pitch with central yellow zone', NULL, NULL, NULL, true, true, true, NULL, 140),
  ('11v11 protect the central forward zone', 'conditioned_game', 'opposed', 'out_of_possession', 117, 117, 'Session for Tactical Situation 8: Practice 3', 'Simeone (Atletico Madrid)', 'Front block defends the crucial central area in a full game and counters on winning the ball.', 'Full 11v11 with GKs; a central yellow zone marked in front of the reds'' defence with side channels.', 'White GK starts; whites try to score. Reds defend as a compact block, blocking passes into the forwards in the central zone, and break quickly when they win it.', 'Whites'' goal counts 3 if scored after a pass into a forward in the central yellow zone. Reds must score within 8-15 seconds of a win.', NULL, 'Shift with the ball; read the situation; keep horizontal and vertical distances.', '11v11', 22, 22, 'Full pitch', NULL, NULL, NULL, true, true, true, NULL, 150),
  ('Rear block controls wide zones', 'defending', 'overload', 'out_of_possession', 133, 134, 'Practice for Tactical Situation 9', 'Simeone (Atletico Madrid)', 'Rear block (midfield four and back four) shares out wide zones between wide midfielder and full back and deals with passes to full backs and long balls to wingers.', 'Half pitch to a big goal with GK; each flank has a 12-yard-long strip split in two (yellow higher zone for the wide midfielder, white lower zone for the full back). About 10 whites (3 deep players, full backs, wingers, midfielders, striker) v 8 reds; 2 mini goals at halfway for the red counter.', 'The 3 deep whites circulate while reds shift and keep a safe distance; when a centre back carries forward reds drop. Scenario A: pass to the advancing strong-side full back while the winger moves inside. Scenario B: long pass to the winger on the weak side. Whites try to score; reds win it and counter.', 'Reds score in either mini goal within 8-10 seconds of winning the ball.', 'Full backs first let wide players receive, then after a few minutes try to intercept before the ball arrives; can be set against any formation.', 'Shift with the ball; read the situation; keep checking the wide areas; decide according to opponents'' movements.', 'approx 10v8+GK', 19, 19, 'Half pitch, 12-yard wide zones split into 2 equal parts', NULL, NULL, NULL, true, true, true, NULL, 160),
  ('Full back and wide mid control winger', 'defending', 'overload', 'out_of_possession', 149, 149, 'Session for Tactical Situation 10: Practice 1', 'Simeone (Atletico Madrid)', 'Full back and wide midfielder react together to a pass to the winger, doubling up and stopping him turning or going inside.', 'Half pitch: 3 white defenders around the centre circle, 2 white wingers in the wide zones (yellow high, white low), a white forward in a central red zone near the box. Reds: 2 full backs and 2 wide midfielders.', 'Whites circulate across the back until a full back plays to the winger. Winger in the white zone: red full back presses at once to stop the turn while the red wide midfielder drops to double mark. Winger in the yellow zone: the wide midfielder takes him, full back holds for balance, pressing with body shape that blocks the pass to the forward.', NULL, NULL, 'Check the wide areas; read the winger''s position; double mark and block the inside pass to No.9.', '6v4', 10, 10, 'Half pitch with wide zones and a central red zone', NULL, NULL, NULL, false, false, true, NULL, 170),
  ('Zonal small sided game wide double marking', 'defending', 'overload', 'out_of_possession', 150, 151, 'Session for Tactical Situation 10: Practice 2', 'Simeone (Atletico Madrid)', 'Wide pair applies double marking or press-and-cover while central midfielders and full backs protect the forward and the space behind.', 'As practice 1 plus 2 red central midfielders, 3 white central midfielders, a big goal with GK and 2 red mini goals near halfway; a central red zone for the forward and long red channels down each side behind the full backs.', 'Whites try to get the ball to the forward in the central zone (who shoots or crosses) or to an attacking midfielder in a wide red channel who crosses. Scenario A: both red wide players double the winger. Scenario B: winger drops deep, red wide midfielder presses while the full back stays deep to cover the run behind, and the nearest red CM blocks the lane to the forward. Reds counter into the mini goals.', 'Winger may not pass backwards once he receives. White full backs and defensive midfielder only enter the playing area after reds win the ball.', 'Scenario A double marking; Scenario B wide midfielder presses and full back drops off to cover.', 'Read the situation; wide pair communicate about the winger; check wide areas often; right decision for each situation.', '9v6+GK', 16, 16, 'Half pitch with zones', NULL, NULL, NULL, true, true, true, NULL, 180),
  ('9v9 force play wide and defend it', 'conditioned_game', 'opposed', 'out_of_possession', 152, 152, 'Session for Tactical Situation 10: Practice 3', 'Simeone (Atletico Madrid)', 'Rear block funnels the ball wide then stops short passes to the winger in a game.', '9v9 on a large area with a goal and GK at each end; marked wide zones (white and yellow) on each flank, optional.', 'White GK starts and whites attack. Reds force the ball wide and defend potential short passes to the winger, reacting to his position, then win it and counter to score.', NULL, '11v11 on two thirds of the pitch: whites score any way, but a goal after a short pass in a wide area counts 3; reds score on the counter within a set time.', NULL, '9v9', 18, 22, 'Large area (progression 2/3 pitch)', NULL, NULL, NULL, true, true, true, NULL, 190),
  ('Cover the centre back pulled wide 4v6', 'defending', 'overload', 'out_of_possession', 159, 159, 'Session for Tactical Situation 11: Practice 1', 'Simeone (Atletico Madrid)', 'Deepest central midfielder drops into the back line when a centre back is dragged out to the side-line.', 'Penalty area region with big goal and GK; 3 white defenders passing at halfway, white wide players, attacking midfielder and forward against 4 reds (full back, 2 centre backs, deepest CM) in front of a central red zone.', 'Whites circulate and reds shift. When a white full back reaches the wide area, the attacking midfielder runs into the channel, receives and crosses for the forward. The red centre back follows him wide and the deepest CM runs back to fill the gap and make 2v1 in the central area. Reds stop or defend the cross, then reset.', NULL, NULL, 'Centre back and central midfielder move in sync.', '6v4+GK', 11, 11, 'Final third with central red zone', NULL, NULL, NULL, true, true, true, NULL, 200),
  ('Fill the gap after centre back shift 6v8', 'defending', 'overload', 'out_of_possession', 160, 161, 'Session for Tactical Situation 11: Practice 2', 'Simeone (Atletico Madrid)', 'Rear block chooses the right cover when a centre back is pulled wide: midfielder drops, full back covers, or both.', 'As practice 1 with extra 5 x 8 yard blue wide zones for 2 red full backs and 2 white wingers; white full backs may pass to wingers or attacking midfielders.', 'White full back plays a long ball for the attacking midfielder''s run behind the red full back; the red centre back tracks him wide. Scenario A: full back is marking the winger, so the deepest CM drops into the line. Scenario B: full back is already deep and covers the shift himself, so the CM stays. Reds defend the cross and reset.', NULL, 'Scenario A central midfielder drops to fill; Scenario B full back deep enough to cover; option where both drop for extra safety.', 'Read the situation; talk about who covers; centre back and CM in sync; full back reacts to the situation.', '8v6+GK', 15, 15, 'Final third, wide zones 5 x 8 yards', NULL, NULL, NULL, true, true, true, NULL, 210),
  ('Functional game defending crosses from wide', 'conditioned_game', 'opposed', 'out_of_possession', 162, 162, 'Session for Tactical Situation 11: Practice 3', 'Simeone (Atletico Madrid)', 'Rear block applies its cover reactions to centre back shifts in a game and counters after winning it.', '8 (+GK) reds v 9 whites on a large area with a big goal and GK; 2 mini goals at halfway for the reds; marked wide areas on each flank.', 'Whites start and attack, looking to receive in wide areas and cross. Reds react per the earlier practices and on winning the ball counter into the 2 mini goals.', 'A white goal from a cross after receiving in the wide area counts double.', '11v11 on two thirds of the pitch: whites score any way, a goal from a cross after a pass behind the full back counts 3; reds counter within a set time.', NULL, '8(+GK)v9', 18, 22, 'Large area (progression 2/3 pitch)', NULL, NULL, NULL, true, true, true, NULL, 220),
  ('Rear block reacts to wide receivers', 'defending', 'opposed', 'out_of_possession', 183, 184, 'Session for Tactical Situation 12: Practice 1', 'Simeone (Atletico Madrid)', 'Rear block and midfield react correctly when an opposing full back or winger receives wide, using double marking and cover to block inside passes.', 'Final third with a big goal and GK; a 12-yard channel on each flank split into a deep and an advanced zone, and a central zone in front of the box. White back four passes along the back; reds (defenders plus midfielders) defend in a 4-4 block, whites have a winger on each side, two central attackers and a forward.', 'Whites circulate across their back line while reds shift with the ball. Scenario A: a centre back finds the full back pushing into the advanced zone while the winger comes inside; Scenario B: the centre back plays a through ball to the weak-side winger who has drifted inside between the lines. Whites try to turn and score; reds react depending on whether their centre back is close to or far from the strong side and whether the receiver is deep or advanced.', 'Red midfielders must not block the through pass to the winger (Scenario B).', 'Scenario A (full back receives advanced) then Scenario B (winger receives between the lines).', 'Centre back talks to his team-mate about his own position; full back keeps an open body shape to see opponents and team-mates; choose the reaction that fits the exact situation.', 'about 8 attackers v 8 defenders + GK (from diagram)', 17, 17, 'final third; wide zones 12 yards long', NULL, NULL, NULL, true, true, true, NULL, 230),
  ('Wide-reaction game with counter mini goals', 'conditioned_game', 'opposed', 'out_of_possession', 185, 185, 'Session for Tactical Situation 12: Practice 2 (Progression)', 'Simeone (Atletico Madrid)', 'Apply the rear block''s wide-area defensive reactions in a free game and counter after winning the ball.', 'Half pitch: reds (8 outfield + GK) defend a big goal; whites (9) attack it; three mini goals on the halfway line for the reds to counter into.', 'Normal game. Whites try to score in the big goal; reds defend the situations from the analysis, win the ball and counter into the three mini goals.', 'Whites'' goal counts double if it comes after a coordinated move between their full back and winger.', '11v11 on two thirds of the pitch: whites score three if the goal follows a pass to the overlapping full back or a through ball to a winger who has moved central; reds must counter and score within a time limit.', NULL, '8 (+GK) v 9', 18, 22, 'half pitch (progression two thirds of pitch)', NULL, NULL, NULL, true, true, true, NULL, 240),
  ('Centre backs track forwards'' movements', 'defending', 'opposed', 'out_of_possession', 194, 194, 'Session for Tactical Situation 13: Practice 1', 'Simeone (Atletico Madrid)', 'Centre backs read whether a forward drops deep or stays high and step up, follow or pass him on, while the block keeps the gap between lines tight.', 'Final third with goal and GK; two box-wide zones, each 6 yards long, marked in front of the area (the deeper one for defenders, the higher one for midfielders). White back four plus a central midfielder, two forwards and wingers against a red back four and midfield.', 'White defenders pass across while reds shift. When the ball reaches the white central midfielder a through pass is on; the strong-side white forward shows either high (in the defenders'' zone) or deep (in the midfield zone). The nearest red centre back reads it and reacts, and reds try to stop whites scoring.', 'Red midfielders do not block the through pass to the forward.', NULL, 'Key reads: is the first forward high or deep, and is the second forward close enough to attack the space behind the centre back.', 'about 8 attackers v 8 defenders + GK (from diagram)', 17, 17, 'final third; two zones box width x 6 yards', 5.5, 40.2, NULL, true, true, true, NULL, 250),
  ('Centre-back reactions game with mini-goal counters', 'conditioned_game', 'opposed', 'out_of_possession', 195, 195, 'Session for Tactical Situation 13: Practice 2 (Progression)', 'Simeone (Atletico Madrid)', 'Rear block defends forwards dropping or running in behind in a live game, then counters quickly.', 'Half pitch: reds (8 outfield + GK) defend a big goal; whites (9) attack; three mini goals on the halfway line.', 'Normal game with whites trying to play through the middle. Reds use the centre-back reactions from the analysis, win the ball and counter into a mini goal.', 'Whites score two if the goal follows a pass to a dropping forward or uses space left behind a red centre back; reds must score their counter within a set time, e.g. 10 seconds.', 'Whites also use coordinated full back and winger movements so the rear block faces more situations.', 'Read the situation; keep talking; watch where the first and second forwards are.', '8 (+GK) v 9', 18, 18, 'half pitch', NULL, NULL, NULL, true, true, true, NULL, 260),
  ('High press from GK, force wide', 'conditioned_game', 'opposed', 'out_of_possession', 204, 204, 'Practice for Tactical Situation 14', 'Simeone (Atletico Madrid)', 'Press high from the opposing goalkeeper, create a strong side and keep the ball out of the centre.', 'Half pitch: whites (10 + GK) build up from their goal; a large central zone runs the length of the area; three mini goals on the halfway line for the whites. Reds (10) press in a 4-4-2.', 'Coach starts with a long ball to the white GK. Whites build out under pressure and try to score in any mini goal; reds press at once, steer play to one side, mark every nearby receiver and try to outnumber around the ball.', 'Whites score three if their goal comes from inside the central zone. If a white player receives in the central zone, reds must block his pass or win the ball within 3-5 seconds.', NULL, 'Force the ball wide and build a strong side; stop the opponents switching to the weak side.', '10 v 10 (+GK)', 21, 21, 'half pitch with large central zone', NULL, NULL, NULL, true, true, true, NULL, 270),
  ('Press after GK pass with central zones', 'defending', 'opposed', 'out_of_possession', 225, 226, 'Practice for ''Pressing After the Goalkeeper''s Pass'' (Tactical Situation 15)', 'Simeone (Atletico Madrid)', 'Team pressing from the opposition goalkeeper''s first pass, forcing play wide and keeping the ball out of the central zone while controlling the holding midfielder.', 'Two-thirds pitch with a big goal and GK for the whites at one end and 3 mini goals on the halfway line; the centre is split into a white central zone with a yellow zone in front of the box where the white No.6 operates. Whites line up 4-3-3, reds in Atletico''s 4-4-2.', 'Coach plays a long ball to the white GK; whites build out and try to score in any of the 3 mini goals while reds press from the GK''s first pass or throw. If No.6 receives in the yellow zone from an outfield player the reds close him down at once; if the GK finds No.6 directly the reds force play wide or back; a ball into the white central zone must be blocked or won within 3-5 seconds.', 'A white goal scored from inside the central zone counts 3.', 'White No.6 drops very deep to form a back 3 and reds must adjust; whites switch to 4-4-2 or 4-2-3-1.', 'Force the ball wide and build a strong side; deny the switch to the weak side; control the defensive midfielder.', '10v10 (+GK)', 21, 22, '2/3 pitch', NULL, NULL, NULL, true, true, true, NULL, 280),
  ('Keep a 3v2 at the back, passive', 'passing_opposed', 'passive', 'in_possession', 241, 242, 'Session for Tactical Situation 1 (Transition): Practice 1', 'Simeone (Atletico Madrid)', 'Back line circulates the ball while always keeping a spare man (3v2) behind the ball as cover against a counter.', '40 x 20 yard area with 4 red defenders and 2 passive white forwards inside; 2 red central midfielders and 2 mannequins (standing in for opposing midfielders) just outside, plus a red cone on each side and a coach with balls.', 'Reds pass across the back and work the ball to the strong-side full back, who dribbles out of the area to the red cone. As he goes, either the weak-side full back drops deep (Scenario A) or the weak-side central midfielder drops in (Scenario B) so a 3v2 remains against the 2 forwards.', 'Reds must keep a 3v2 inside the area at all times; whites press passively.', 'Switch between the two options (full back drops / midfielder drops) in sync without ever going unbalanced.', 'Full backs pick a high or very high starting spot relative to the mannequin midfielders; synchronised movement and talk.', '6v2', 8, 8, '40 x 20 yards', 36.6, 18.3, NULL, false, false, false, NULL, 290),
  ('Build up keeping 3v2, 7v8 game', 'transition', 'opposed', 'to_defend', 243, 243, 'Session for Tactical Situation 1 (Transition): Practice 2', 'Simeone (Atletico Madrid)', 'Build up while retaining a 3v2 spare man at the back so the team is safe if possession is lost and the opposition counters.', '40 x 60 yard pitch with a 40 x 20 low zone at one end holding 2 mini goals; big goal with GK at the far end. Reds: 4 defenders, 2 central midfielders, 1 forward; whites: 2 forwards in the low zone, 4 midfielders and 2 centre backs.', 'Coach feeds the reds, who build up through the low zone keeping a 3v2 behind the ball, then play forward to score past the GK. Whites try to win it and counter into the 2 mini goals.', 'During red build-up the 2 white forwards must stay in the low zone; once whites win the ball they may move anywhere.', NULL, 'Full backs high or very high according to the opposing central midfielders; synchronised movement and communication.', '7v8 (+GK)', 16, 16, '40 x 60 yards', 54.8, 36.6, NULL, true, true, true, NULL, 300),
  ('Lost long pass transition game', 'transition', 'opposed', 'to_defend', 250, 250, 'Practice for Tactical Situation 2 (Negative Transition After Losing Possession from a Long Pass)', 'Simeone (Atletico Madrid)', 'React correctly when a long ball forward is intercepted: recover, get compact, block through passes and push play wide.', '11v11 on two-thirds of a pitch split into 3 zones: a red low zone at the reds'' goal, a white central zone, and a yellow zone near the white goal where the red forwards sit.', 'Red GK starts; reds build up with the weak-side full back or a central midfielder dropping to make a back 3 (3v2). A red defender or midfielder must then hit a long pass from the low zone towards a forward in the yellow zone; a white centre back intercepts and the reds must run the negative transition to stop whites scoring.', 'The long pass must be played from within the low zone.', 'Move to 11v11 on a full pitch with the same focus on losing the ball.', 'Full backs high or very high relative to the opposing central midfielder; block passes into the white central zone and force the ball wide.', '11v11', 22, 22, '2/3 pitch', NULL, NULL, NULL, true, true, true, NULL, 310),
  ('Lost switch of play transition vs 4-4-2', 'transition', 'opposed', 'to_defend', 256, 256, 'Practice for Tactical Situation 3 (Negative Transition After Losing Possession During a Switch of Play)', 'Simeone (Atletico Madrid)', 'Defend the moment a switch of play to the advanced full back is intercepted: shift across, rebuild a strong side and keep the numerical edge at the back.', '11v11 on two-thirds of a pitch with a 30 yard low zone for the red build-up and two 10 x 15 yard side zones out wide at the far end; whites in 4-4-2.', 'Red GK starts; the weak-side central midfielder (No.8) drops to make a back 3. A red defender or midfielder must switch play from the low zone towards a full back in a wide zone; a white full back intercepts and the reds carry out the negative transition to stop a goal.', 'The switch must be played from within the low zone.', 'Change the white formation (4-2-3-1, 4-3-3 etc.).', 'Full backs high or very high according to the opposing wide midfielder.', '11v11', 22, 22, '2/3 pitch; 30 yard low zone; side zones 10 x 15 yards', NULL, NULL, NULL, true, true, true, NULL, 320),
  ('Counter-press after short combinations', 'transition', 'opposed', 'to_defend', 263, 263, 'Practice for Tactical Situation 4 (Counter-Pressing After Losing Possession During Combination Play)', 'Simeone (Atletico Madrid)', 'Attack with short passes and triangles so that the ball can be won back immediately with a counter-press when it is lost.', '11v11 on two-thirds of a pitch with a 30 yard low zone for the reds'' build-up; the pitch can be gridded into small areas.', 'Red GK starts and reds attack with short combination play aiming to score; whites try to win the ball and counter. When reds lose it, the nearby players are close enough to press the new ball carrier at once.', 'Red passes no longer than 10-15 yards; if gridded, reds may only pass into neighbouring areas.', NULL, 'Good movement off the ball to form triangles; synchronised movement and communication.', '11v11', 22, 22, '2/3 pitch; 30 yard low zone', NULL, NULL, NULL, true, true, true, NULL, 330)
) AS v(t, cat, opp, m, pf, pt, ref, coach, obj, setup, proc, rules, prog, cp, players, mn, mx, area, len, wid, dur, goals, gk, dir, age, so)
JOIN exercise_categories c ON c.code = v.cat
CROSS JOIN (SELECT id, source_id FROM coaching_books WHERE slug = 'diego-simeone-defending-tactics-tactical-analysis-and-sessions-from-atl-tico-mad') b;
